<script>
(function(){
  // Check for the actual site's existing booking form and use it where possible.
  var buttons=document.querySelectorAll('.dtt-join-page .dtt-jg-btn');
  var dialog=document.getElementById('dtt-join-fallback');
  var selected=document.getElementById('dtt-join-selected');
  var copy=document.getElementById('dtt-join-copy');
  var close=document.getElementById('dtt-join-close');
  var current='';
  buttons.forEach(function(btn){btn.addEventListener('click',function(){
    current=btn.getAttribute('data-safari')+' — '+btn.getAttribute('data-price')+' per person';
    window.dttSelectedJoiningSafari=current;
    if(typeof window.openBookingPopup==='function'){
      window.openBookingPopup();
      return;
    }
    selected.textContent=current;
    if(dialog&&typeof dialog.showModal==='function')dialog.showModal();
    else alert('Please contact Deep Tanzania Tours to enquire about: '+current);
  });});
  if(copy)copy.addEventListener('click',function(){
    var line='Hello Deep Tanzania Tours, I would like to enquire about joining '+current+'. Please share available dates and booking details.';
    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(line).then(function(){copy.textContent='Copied!';},function(){window.prompt('Copy your message:',line);});}
    else window.prompt('Copy your message:',line);
  });
  if(close)close.addEventListener('click',function(){dialog.close();copy.textContent='Copy enquiry';});
  // Support headers that are absolutely positioned over page content.
  function correctHeaderOverlap(){
    var page=document.querySelector('.dtt-join-page');if(!page||window.scrollY>15)return;
    page.style.paddingTop='0px';var pt=page.getBoundingClientRect().top,bottom=0;
    document.querySelectorAll('header,#header,#main-header,.site-header,.main-header,.header-container,.header-wrapper,.header-area,.navbar,nav').forEach(function(el){
      if(page.contains(el))return;var r=el.getBoundingClientRect();
      if(r.width<100||r.height<15||r.height>340||r.top>135||r.bottom<=0||r.bottom>360)return;
      bottom=Math.max(bottom,r.bottom);
    });
    if(bottom>pt+3)page.style.paddingTop=Math.ceil(bottom-pt+12)+'px';
  }
  correctHeaderOverlap();
  window.addEventListener('load',correctHeaderOverlap,{once:true});
  window.addEventListener('resize',correctHeaderOverlap,{passive:true});
})();
</script>
